import csv

# Регулярное выражение для ключа вида XXXX-XXXX-XXXX-XXXX (A-Z, 0-9)
LICENSE_PATTERN = re.compile(r'^[A-Z0-9]{4}(?:-[A-Z0-9]{4}){3}$')


class LicenseError(ValueError):
    """Ошибка валидации лицензии/ключа."""
    pass


def validate_license(key: str) -> bool:
    """
    Проверяет формат лицензионного ключа.

    Принимает строку вида XXXX-XXXX-XXXX-XXXX (A-Z, 0-9).
    Возвращает True при совпадении, иначе бросает LicenseError.
    """
    if not isinstance(key, str):
        raise LicenseError("Ключ должен быть строкой")
    key = key.strip()
    if not key:
        raise LicenseError("Ключ не может быть пустым")
    if LICENSE_PATTERN.fullmatch(key):
        return True
    raise LicenseError(f"Неверный формат ключа: {key}")


def main():
    allowed_licenses = {
        'MIT', 'BSD-3-Clause', 'Apache-2.0', 'Public Domain', 'Проприетарная'
    }
    allowed_count = 0
    needs_review_count = 0

    with open('компоненты.csv', 'r', encoding='utf-8', newline='') as f:
        reader = csv.reader(f, delimiter=';')
        next(reader, None)  # пропустить заголовок
        for row in reader:
            if len(row) < 2:
                continue
            component = row[0].strip()
            license_ = row[1].strip()
            if license_ in allowed_licenses:
                status = 'допустима'
                allowed_count += 1
            else:
                status = 'требует проверки'
                needs_review_count += 1
            print(f'{component} — {license_} — {status}')

    print(f'Итого: допустимо — {allowed_count}, требует проверки — {needs_review_count}')


if __name__ == '__main__':
    main()
